"""Memory schema types for the Mantle runtime.

These are static, Pydantic models loaded from ``memory.yml`` at model-load
time. They describe the shape of a skill's memory — they carry no runtime
state.

- :class:`SkillMemorySchema` — a skill's public and private fields.
- :class:`ProjectMemorySchema` — project-wide shared fields (YAML loader
  included).
- :class:`SkillMemoryContract` — maps skill ``memory.yml`` (top-level
  ``schema:``) onto :class:`SkillMemorySchema`; stored on
  :class:`~rasa.mantle.skills.skill.Skill`.

**Slot name format** (enforced by
:class:`~rasa.mantle.memory.manager.MemoryManager`):

- Skill entry:   ``{skill_id}.{entry_name}``  (e.g. ``transfer_money.amount``)
- Project entry: ``project.{entry_name}``     (e.g. ``project.authenticated``)
- System entry:  ``system.{entry_name}``      (e.g. ``system.language``)
- Unknown:       ``{entry_name}`` verbatim    (DEBUG log emitted)
"""

from __future__ import annotations

from pathlib import Path

import yaml  # type: ignore[import-untyped]
from pydantic import BaseModel, ConfigDict, Field

from rasa.mantle.memory.field import MemoryField


class SkillMemorySchema(BaseModel):
    """Memory schema for a single skill, split into public and private fields.

    ``public`` fields are readable by any skill via
    :meth:`~rasa.mantle.memory.manager.MemoryManager.read_all`. ``private``
    fields are only readable while this skill is active.
    """

    model_config = ConfigDict(frozen=True)

    public: dict[str, MemoryField] = Field(default_factory=dict)
    private: dict[str, MemoryField] = Field(default_factory=dict)

    def all_fields(self) -> dict[str, MemoryField]:
        """Return all fields (public and private) as a flat dict.

        Private fields override public fields on name collision.
        """
        return {**self.public, **self.private}


class ProjectMemorySchema(BaseModel):
    """Project-wide memory schema shared across all skills."""

    model_config = ConfigDict(frozen=True)

    fields: dict[str, MemoryField] = Field(default_factory=dict)

    @classmethod
    def from_yaml(cls, path: Path) -> "ProjectMemorySchema":
        """Load a project memory schema from a YAML file.

        The file should be a flat mapping of field name → field attributes::

            authenticated:
              type: bool
            account_id:
              type: text
              pii: true

        Args:
            path: Path to the YAML file. A missing file returns an empty schema.

        Returns:
            A loaded :class:`ProjectMemorySchema` instance.
        """
        if not path.exists():
            return cls()
        with path.open(encoding="utf-8") as fh:
            raw = yaml.safe_load(fh) or {}
        fields: dict[str, MemoryField] = {
            name: MemoryField.model_validate(attrs if isinstance(attrs, dict) else {})
            for name, attrs in raw.items()
        }
        return cls(fields=fields)


class SkillMemoryContract(BaseModel):
    """Map skill ``memory.yml`` onto :class:`SkillMemorySchema`.

    The file's top-level key is ``schema:`` (Python name ``definition``).
    :class:`SkillMemorySchema` is only ``public`` / ``private``, so it cannot
    validate that mapping directly.
    """

    model_config = ConfigDict(frozen=True, populate_by_name=True)

    definition: SkillMemorySchema = Field(
        default_factory=SkillMemorySchema, alias="schema"
    )
